from functools import cache
from typing import List
from test_suite import time_soln, test_all

class Solution:
    def hasValidPath(self, grid: list[list[str]]) -> bool:
        if grid[0][0] == ')' or grid[-1][-1] == '(': return False

        m = len(grid)
        n = len(grid[0])

        map = {'(':1, ')':-1}
        points = [ [set() for _ in range(n)] for _ in range(m) ]

        # fill first element
        points[0][0].add( 1 )

        # fill table
        for r in range(m):
            for c in range(n):
                steps_rem = m-r-1 + n-c-1
                check_list = set()
                if c > 0: check_list.update(points[r][c-1])
                if r > 0: check_list.update(points[r-1][c])
                for e in check_list:
                    v = e+map[grid[r][c]]
                    if 0 <= v <= steps_rem:
                        points[r][c].add(v)

        return 0 in points[-1][-1]

    def hasValidPath_cached(self, grid: List[List[str]]) -> bool:
        m, n = len(grid), len(grid[0])
        map = {'(':1, ')':-1}

        # Boundary checks (odd steps, start on end, end on start)
        if (m+n)%2 == 0 or grid[0][0] == ')' or grid[-1][-1]=='(':
            return False

        @cache
        def traverse(r:int, c:int, k:int) -> bool:
            # update current value
            v = k + map[ grid[r][c] ]

            # check if end
            if r == m-1 and c == n-1:
                return v == 0

            # prune (current is negative or not enough steps left)
            if v < 0 or m-r+n-c-1 < v:
                return False

            # continue down and right
            res = False
            if r + 1 < m:
                res |= traverse(r+1, c, v)
            if c + 1 < n:
                res |= traverse(r, c+1, v)

            return res

        return traverse(0,0,0)


    def hasValidPath_reversed(self, grid: List[List[str]]) -> bool:
        '''
        Same as the cached version, but traverses from the end to the start. 
        '''
        m, n = len(grid), len(grid[0])
        map = {'(':-1, ')':1}

        # Boundary checks (odd steps, start on end, end on start)
        if (m+n)%2 == 0 or grid[0][0] == ')' or grid[-1][-1]=='(':
            return False

        @cache
        def traverse(r:int, c:int, k:int) -> bool:
            # update current value
            v = k + map[ grid[r][c] ]

            # prune (current is negative or not enough steps left)
            if v < 0 or r+c < v:
                return False

            # check if end
            if r == c == 0:
                return v == 0

            # continue down and right
            res = False
            if r > 0:
                res = res or traverse(r-1, c, v)
            if c > 0:
                res = res or traverse(r, c-1, v)

            return res

        return traverse(m-1,n-1,0)

    

    def hasValidPath_reversed_opt(self, grid: List[List[str]]) -> bool:
        '''
        Same as the cached version, but traverses from the end to the start. 
        '''
        m, n = len(grid), len(grid[0])
        map = {'(':-1, ')':1}

        # Boundary checks (odd steps, start on end, end on start)
        if (m+n)%2 == 0 or grid[0][0] == ')' or grid[-1][-1]=='(':
            return False

        @cache
        def traverse(r:int, c:int, k:int) -> bool:
            # update current value
            v = k + map[ grid[r][c] ]

            # prune (current is negative or not enough steps left)
            if v < 0 or r+c < v:
                return False

            # check if end
            # if r == c == 0:
            if r ==0 and c==0:
                return v == 0

            # continue down and right
            res = False
            if r > 0:
                res = res or traverse(r-1, c, v)
            if c > 0:
                res = res or traverse(r, c-1, v)

            return res

        return traverse(m-1,n-1,0)


if __name__ == '__main__':
    sol = Solution()

    test_funcs = [
        # sol.hasValidPath,
        # sol.hasValidPath_cached,
        sol.hasValidPath_reversed,
        sol.hasValidPath_reversed_opt,
    ]

    test_all(
        test_cases,
        test_funcs
    )
